<script setup>
import MultimediaPublicacion from '../components/MultimediaPublicacion.vue'
import { ref, computed, watch } from 'vue'
import { useRoute } from 'vue-router'
import { apiFetch } from '../services/api.js'
import { usuario, exigirSesion } from '../services/sesion.js'
import AvatarUsuario from '../components/AvatarUsuario.vue'
import { formatearFecha } from '../utils/formato.js'
const route=useRoute(), tab=ref('publicaciones'), orden=ref('relevancia'), dias=ref('0'), categoria=ref(''), minimo=ref(''), etiqueta=ref(''), tipoFiltro=ref(''), estado=ref(''), alcance=ref('todas')
const items=ref([]), categorias=ref([]), cargando=ref(false), mas=ref(false), error=ref(''), errorCategorias=ref(''), cargandoCategorias=ref(false), siguiendo=ref(false)
const q=computed(()=>typeof route.query.q==='string'?route.query.q.trim().slice(0,120):'')
const relacionadas=computed(()=>q.value?categorias.value.filter(c=>`${c.nombre} ${c.descripcion||''}`.toLowerCase().includes(q.value.toLowerCase())):[])
const filtrosContenido=computed(()=>['publicaciones','multimedia','interacciones'].includes(tab.value))
let version=0,versionCat=0
async function cargarCategorias(){const v=++versionCat;cargandoCategorias.value=true;errorCategorias.value='';try{const r=await apiFetch('foro','/categorias');if(v===versionCat)categorias.value=r}catch(e){if(v===versionCat)errorCategorias.value=e.message}finally{if(v===versionCat)cargandoCategorias.value=false}}
async function cargar(agregar=false){const v=++version;error.value='';mas.value=false;if(!agregar)items.value=[];if(!q.value||tab.value==='categorias'){cargando.value=false;return}cargando.value=true
  try{const params=new URLSearchParams({q:q.value,orden:orden.value,dias:dias.value,min_votos:minimo.value,offset:String(items.value.length)});let r,lista,hay
    if(tab.value==='usuarios'){r=await apiFetch('usuarios',`/usuarios/buscar?${new URLSearchParams({q:q.value,offset:String(items.value.length)})}`);lista=r.usuarios;hay=r.hay_mas}
    else if(tab.value==='comunidades'){r=await apiFetch('foro',`/comunidades?${new URLSearchParams({q:q.value,offset:String(items.value.length)})}`);lista=r.slice(0,20);hay=r.length>20}
    else if(tab.value==='interacciones'){params.set('categoria',categoria.value||'0');r=await apiFetch('foro',`/preguntas/buscar-interacciones?${params}`);lista=r.resultados;hay=r.hay_mas}
    else{params.set('limite','21');params.set('vista',usuario.value?alcance.value:'todas');params.set('etiqueta',etiqueta.value);params.set('estado',estado.value);params.set('tipo',tab.value==='multimedia'?'multimedia':tipoFiltro.value);const ruta=categoria.value?`/preguntas/categoria/${categoria.value}`:'/preguntas';r=await apiFetch('foro',`${ruta}?${params}`);lista=r.slice(0,20);hay=r.length>20}
    if(v===version){items.value.push(...lista);mas.value=hay}
  }catch(e){if(v===version)error.value=e.message}finally{if(v===version)cargando.value=false}}
async function seguir(c){if(siguiendo.value||!exigirSesion('Inicia sesión para seguir categorías.'))return;siguiendo.value=true;try{await apiFetch('foro',`/categorias/${c.id}/seguir`,{method:'PUT',body:JSON.stringify({seguir:!c.siguiendo})});await cargarCategorias();window.dispatchEvent(new Event('categorias-actualizadas'))}catch(e){errorCategorias.value=e.message}finally{siguiendo.value=false}}
watch([q,tab,orden,dias,categoria,minimo,etiqueta,tipoFiltro,estado,alcance,()=>usuario.value?.id],()=>cargar(),{immediate:true})
watch(()=>usuario.value?.id,()=>{categorias.value=[];cargarCategorias()},{immediate:true})
</script>
<template>
<main class="pagina pagina-buscar"><h1>Resultados de búsqueda</h1><p v-if="q" class="tarjeta-meta">Resultados para «{{q}}»</p><p v-else class="foro-vacio">Escribe algo en el buscador superior.</p>
<div class="perfil-tabs" role="group" aria-label="Tipo de resultado"><button v-for="t in [{id:'publicaciones',n:'Publicaciones'},{id:'categorias',n:'Categorías'},{id:'comunidades',n:'Comunidades'},{id:'interacciones',n:'Respuestas y comentarios'},{id:'multimedia',n:'Multimedia'},{id:'usuarios',n:'Usuarios'}]" :key="t.id" class="chip" :class="{'chip-activo':tab===t.id}" :aria-pressed="tab===t.id" @click="tab=t.id">{{t.n}}</button></div>
<div class="home-rejilla"><div class="home-principal">
<div v-if="filtrosContenido" class="feed-filtros filtros-busqueda"><label>Orden<select v-model="orden"><option value="relevancia">Relevancia</option><option value="reciente">Recientes</option><option value="antiguo">Antiguas</option><option value="popular">Popularidad</option></select></label><label>Fecha<select v-model="dias"><option value="0">Siempre</option><option value="1">Último día</option><option value="7">Última semana</option><option value="30">Último mes</option><option value="365">Último año</option></select></label><label>Categoría<select v-model="categoria"><option value="">Todas</option><option v-for="c in categorias" :key="c.id" :value="String(c.id)">{{c.nombre}}</option></select></label><label>Votos mínimos<select v-model="minimo"><option value="">Cualquiera</option><option value="1">1+</option><option value="5">5+</option><option value="10">10+</option></select></label><template v-if="tab==='publicaciones'||tab==='multimedia'"><label v-if="usuario">Buscar en<select v-model="alcance"><option value="todas">Todo el foro</option><option value="personalizado">Siguiendo</option><option value="guardadas">Guardadas</option><option value="ocultas">Ocultas</option></select></label><label>Etiqueta<select v-model="etiqueta"><option value="">Todas</option><option v-for="e in ['duda','debate','recurso','anuncio','proyecto']" :key="e">{{e}}</option></select></label><label v-if="tab==='publicaciones'">Tipo<select v-model="tipoFiltro"><option value="">Todos</option><option v-for="t in ['texto','imagen','enlace','encuesta','multimedia','video']" :key="t">{{t}}</option></select></label><label>Estado<select v-model="estado"><option value="">Todos</option><option value="resuelta">Resueltas</option><option value="pendiente">Pendientes</option></select></label></template></div>
<p v-if="error" class="error" role="alert">{{error}} <button class="btn-texto" @click="cargar()">Reintentar</button></p>
<template v-if="tab==='categorias'"><p v-if="cargandoCategorias" role="status">Cargando categorías…</p><p v-else-if="!relacionadas.length&&!errorCategorias" class="foro-vacio">No se encontraron categorías.</p><article v-for="c in relacionadas" :key="c.id" class="tarjeta-pregunta"><h2><router-link :to="{path:'/',query:{categoria:String(c.id)}}">{{c.nombre}}</router-link></h2><p>{{c.descripcion}}</p><button class="btn-secundario" :disabled="siguiendo" @click="seguir(c)">{{c.siguiendo?'Dejar de seguir':'Seguir'}}</button></article></template>
<template v-else><div v-if="cargando&&!items.length" role="status" aria-label="Cargando resultados"><div v-for="n in 3" :key="n" class="skeleton-tarjeta"><i></i><i></i><i></i></div></div><p v-else-if="q&&!items.length&&!error" class="foro-vacio">No encontramos resultados. Prueba otra búsqueda o cambia los filtros.</p>
<ul class="foro-lista"><li v-for="r in items" :key="`${r.tipo||tab}-${r.id}`" class="tarjeta-pregunta resultado-item">
<template v-if="tab==='comunidades'"><div><h2><router-link :to="`/comunidades/${r.slug}`">{{r.nombre}}</router-link></h2><p>{{r.descripcion}}</p><p class="nota-demo">{{r.tematica}} · {{r.miembros}} miembros</p></div></template><template v-else-if="tab==='usuarios'"><div class="perfil-identidad"><AvatarUsuario :nombre="r.nombre_apellido" :url="r.avatar_url"/><div><router-link :to="`/usuarios/${r.id}`"><strong>{{r.nombre_apellido}}</strong></router-link><p class="nota-demo">{{r.rol}}</p></div></div></template>
<template v-else><div><p class="tarjeta-meta">{{r.nombre_categoria||r.categoria}} · {{r.nombre_autor||r.autor}} · {{formatearFecha(r.fecha_creacion)}}</p><h2><router-link :to="{path:`/preguntas/${r.id_pregunta||r.id}`,hash:tab==='interacciones'?`#${r.tipo}-${r.id}`:''}">{{r.titulo}}</router-link></h2><p class="tarjeta-extracto">{{r.contenido}}</p><p class="nota-demo">{{r.total_votos??r.votos}} votos <template v-if="tab!=='interacciones'">· {{r.cantidad_respuestas}} respuestas</template><template v-else>· {{r.tipo}}</template></p></div><MultimediaPublicacion v-if="['multimedia','video'].includes(r.tipo)" :id="r.id"/><img v-if="r.tipo==='imagen'&&r.recurso_url" :src="r.recurso_url" alt="Imagen de publicación" loading="lazy" referrerpolicy="no-referrer" class="resultado-imagen"/></template></li></ul><button v-if="mas" class="btn-secundario" :disabled="cargando" @click="cargar(true)">Cargar más</button></template></div>
<aside class="home-lateral"><section class="panel-lateral"><h2>Categorías relacionadas</h2><p v-if="errorCategorias" class="error" role="alert">{{errorCategorias}} <button class="btn-texto" @click="cargarCategorias">Reintentar</button></p><p v-else-if="!relacionadas.length&&!cargandoCategorias" class="nota-demo">No hay coincidencias por nombre o descripción.</p><article v-for="c in relacionadas.slice(0,5)" :key="c.id" class="sugerencia"><router-link :to="{path:'/',query:{categoria:String(c.id)}}"><strong>{{c.nombre}}</strong></router-link><p class="nota-demo">{{c.publicaciones}} publicaciones · {{c.seguidores}} miembros</p><button class="btn-secundario" :disabled="siguiendo" @click="seguir(c)">{{c.siguiendo?'Dejar de seguir':'Seguir'}}</button></article></section></aside></div></main>
</template>
